query:
SELECT
  source, siteReferrer,
  count() AS count
FROM {database:Identifier}.records FINAL
WHERE domainId IN {ids:Array(String)}
  AND (source IS NOT NULL OR siteReferrer IS NOT NULL)
  AND created >= {from:DateTime64(3)}
GROUP BY source, siteReferrer
ORDER BY count DESC
LIMIT {limit:UInt64}
